//Generated by AI

using UnityEngine;
using UnityEngine.Audio;
using UnityEngine.UI;
using UnityEngine.Events;

public class AudioSettingsController : MonoBehaviour
{
    [Header("Audio Mixer")]
    [SerializeField] private AudioMixer audioMixer;

    [Header("Volume Sliders")]
    [SerializeField] private Slider musicSlider;
    [SerializeField] private Slider sfxSlider;

    private SettingsManager settingsManager;

    private void Start()
    {
        settingsManager = SettingsManager.Instance;

        if (settingsManager == null)
        {
            Debug.LogError(
                "AudioSettingsController: SettingsManager was not found."
            );

            return;
        }

        // Register the existing Audio Mixer with the central manager
        settingsManager.RegisterAudioMixer(audioMixer);

        // Initialize both sliders and their listeners
        InitializeSlider(
            musicSlider,
            settingsManager.MusicVolume,
            settingsManager.SetMusicVolume,
            "Music"
        );

        InitializeSlider(
            sfxSlider,
            settingsManager.SFXVolume,
            settingsManager.SetSFXVolume,
            "SFX"
        );
    }


    private void InitializeSlider(
        Slider slider,
        float initialValue,
        UnityAction<float> onValueChanged,
        string sliderName)
    {
        if (slider == null)
        {
            Debug.LogError(
                "AudioSettingsController: " + sliderName
                + " Slider is not assigned."
            );

            return;
        }

        // Keep the slider within its configured limits
        float clampedValue = Mathf.Clamp(
            initialValue,
            slider.minValue,
            slider.maxValue
        );

        // Update the slider without invoking its events
        slider.SetValueWithoutNotify(clampedValue);

        // Synchronize the manager with the displayed value
        onValueChanged.Invoke(clampedValue);

        // Listen for future player changes
        slider.onValueChanged.AddListener(onValueChanged);
    }


    private void OnDestroy()
    {
        // Prevent duplicate listeners if this scene is unloaded
        if (settingsManager == null)
            return;

        if (musicSlider != null)
        {
            musicSlider.onValueChanged.RemoveListener(
                settingsManager.SetMusicVolume
            );
        }

        if (sfxSlider != null)
        {
            sfxSlider.onValueChanged.RemoveListener(
                settingsManager.SetSFXVolume
            );
        }
    }
}